WITH valid_inventory AS (SELECT *, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE quantity > 224), summary AS (SELECT CASE WHEN days_since_last_restock >= 68 THEN 'high' WHEN days_since_last_restock >= 18 THEN 'mid' ELSE 'low' END AS days_since_last_restock_bucket, MIN(last_restock) AS min_last_restock, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM valid_inventory GROUP BY CASE WHEN days_since_last_restock >= 68 THEN 'high' WHEN days_since_last_restock >= 18 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE stddev_quantity > 73 ORDER BY stddev_quantity, days_since_last_restock_bucket LIMIT 3
